let t = flow.get("t");
// Se obtienen los datos del flow
let ME_HORNO = flow.get("ME_HORNO");
let f = 1/10;
let A = 200;

let KC = Math.sin(f*t*2*Math.PI) > 0
let KC_1 = Math.sin(f*t*2*Math.PI-0.1) > 0
ME_HORNO.Temp.Value  =  (1/11)*+KC*A + (1/11)*+KC_1*A + (9/11)*ME_HORNO.Temp.Value  

ME_HORNO.KC.Value = KC;

msg = {"payload":ME_HORNO.Temp.Value };




// Se actualiza el tiempo t 
flow.set("t",t+0.1);
flow.set("ME_HORNO",ME_HORNO);
return msg;

