//////////////////////////////////////////////////////////////////

// Instancia de un servidor OPC 

// La documentación para entender las clases y métodos que vamos a utilizar la tenéis en:
//          Documentación general: https://node-opcua.github.io/api_doc/2.32.0/index.html
//          Documentación namespace: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.namespace.html



//////////////////////////////////////////////////////////////////



function constructAlarmAddressSpace(server, addressSpace, eventObjects, done) {
  // server = the created node-opcua server
  // addressSpace = address space of the node-opcua server
  // eventObjects = add event variables here to hold them in memory from this script

  // internal sandbox objects are:
  // node = the compact server node,
  // coreServer = core compact server object for debug and access to NodeOPCUA
  // this.sandboxNodeContext = node context node-red
  // this.sandboxFlowContext = flow context node-red
  // this.sandboxGlobalContext = global context node-red
  // this.sandboxEnv = env variables
  // timeout and interval functions as expected from nodejs



  //////////////////////////////////////////////////////////////////

  // CONFIGURACIONES INICIALES (no modificar)

  //////////////////////////////////////////////////////////////////

  const opcua = coreServer.choreCompact.opcua;
  // Se accede al nodo raíz del espacio de nombres
  // De este nodo raíz se "colgarán" todos los nodos de nuestro servidor
  const rootFolder = addressSpace.findNode("RootFolder");
  const namespace = addressSpace.getOwnNamespace();
  const LocalizedText = opcua.LocalizedText


  // Las variables del flow las obtendremos a partir de this.sandboxFlowContext.
  // En la variable FlowVars se encontrará ME_HORNO, nuestra variable de flow con toda la info del horno
  // Ayuda sobre los tipos de scopes en nodered: https://nodered.org/docs/user-guide/context 
  let FlowVars = this.sandboxFlowContext;


  //////////////////////////////////////////////////////////////////

  // CREACIÓN DEL DISPOSITIVO

  //////////////////////////////////////////////////////////////////


  // Creamos un nuevo nodo tipo objeto que hará las veces de dispositivo
  // Pasarela IIoT
  const device = namespace.addObject({
    organizedBy: addressSpace.rootFolder.objects,
    browseName: "PasarelaModbusOPCUA"
  });

  //////////////////////////////////////////////////////////////////

  // AÑADIR CARPETAS

  //////////////////////////////////////////////////////////////////

  const ME_HORNO = namespace.addObject({
    organizedBy: device,
    browseName: "ME_HORNO"
  });



  //////////////////////////////////////////////////////////////////

  // CREACIÓN DE NODOS EN EL ADDRESS SPACE PARA LAS VARIABLES DE MEs

  //////////////////////////////////////////////////////////////////


  // VARIABLE BOOL SOLO LECTURA
  // La variable se define como un objeto json ({}). Los atributos de este objetos son los atributos del nodo variable que añadimos al namespace
  // El browseName y el nodeID sirve para identificar la variable por su nombre o identificador, respectivamente
  // dataType indica el tipo de dato de la variable. 
  // Value es un objeto con dos métodos: get y set. El método get es una función que devuelve el valor de la variable cuando un cliente realiza una petición.

  // Documentación addVariable: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.namespace.html#addvariable 

  const Horno_KC = namespace.addVariable({
    componentOf: ME_HORNO,
    browseName: "KC",
    displayName: "KC",
    nodeId: "ns=1;s=KC",
    dataType: "Boolean",
    value: {

      get: () => new opcua.Variant({
        dataType: opcua.DataType.Boolean,
        value: FlowVars.get("ME_HORNO")["KC"]["Value"]
      })
    }
  });


  // VARIABLE DOUBLE (REAL en el PLC) SOLO LECTURA
  // En esta ocasión podemos poner unidades a la variable.
  // Con el método addAnalogDataItem También es posible incluir un rango [low, high] de valores
  // documentación addAnalogDataItem: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.namespace.html#addanalogdataitem 


  // Las unidades que soporta el servidor OPC-UA son: ampere, bar, becquerel, byte, centimetre, cubic_centimetre, cubic_centimetre_per_second, cubic_metre, cubic_metre_per_hour, cubic_meter_per_minute,
  //  curie, curie_per_kilogram, degree, degree_celsius, degree_fahrenheit, dots_per_inch, electron_volt, farad, gigabecquerel, gigabyte, gram, hectopascal, hertz, joule, kelvin, kilo_electron_volt, kilobecquerel,
  //  kilobyte, kilohertz, kilogram, kilogram_force, kilogram_per_second, kilogram_per_squared_centimeter, kilometre_per_hour, kilopascal, kilowatt, mega_electron_volt, megabyte, megahertz, megapascal, megawatt,
  //  megawatt_per_minute, metre, metre_per_second, metre_per_second_squared, microsecond, mile_per_hour, millibar, millimetre, millipascal, millisecond, minute, minute_angle, newton, pascal, part_per_million,
  //  percent, pixel, revolutions_per_minute, revolutions_per_second, second, terabyte, volt, watt


  const Horno_Temp = namespace.addAnalogDataItem({
    componentOf: ME_HORNO,
    browseName: "Temp",
    displayName: "Temp",
    nodeId: "ns=1;s=Temp",
    description: FlowVars.get("ME_HORNO")["Temp"]["Descripcion"],
    dataType: 'Double',
    eventSourceOf: ME_HORNO, // Para poder poner una alarma
    engineeringUnitsRange: {
      low: 0,
      high: 400
    },

    engineeringUnits: opcua.standardUnits.degree_celsius,

    value: {
      get: () => new opcua.Variant({
        dataType: opcua.DataType.Double,
        value: FlowVars.get("ME_HORNO")["Temp"]["Value"]
      })
    }
  });



  // VARIABLE CON ESCRITURA 
  // El valor que escribe el cliente se recoge en el método set del atributo Value. Este método es una función que recibe y procesa el valor indicado por el cliente.
  // En nuestro caso el valor leído se guarda en un buffer alojado en el contexto flow (variables de flujo). Posteriormente, los valores de este buffer serán procesados y enviados
  //  al flujo de comunicaciones de modbus para enviarlos al PLC mediante los nodos write de modbus.

  const Horno_MOD_SP_TEnf = namespace.addVariable({
    componentOf: ME_HORNO,
    browseName: "MOD_SP_TEnf",
    nodeId: "ns=1;s=MOD_SP_Temp",
    displayName: "MOD_SP_TEnf",
    description:
      new LocalizedText({ text: FlowVars.get("ME_HORNO")["MOD_SP_TEnf"]["Descripcion"], locale: 'es-ES' }),

    dataType: "Double",
    value: {
      get: () => new opcua.Variant({
        dataType: opcua.DataType.Double,
        value: FlowVars.get("ME_HORNO")["MOD_SP_TEnf"]["Value"]
      }),

      set: function (variant) {

        vari = FlowVars.get("bufferEnvio").push({ "ME_HORNO": { "name": "MOD_SP_TEnf", "value": variant.value } });
        return opcua.StatusCodes.Good;
      }
    }
  });




  //////////////////////////////////////////////////////////////////

  // VARIABLES CON HISTÓRICOS

  //////////////////////////////////////////////////////////////////

  // OPC permite guardar datos históricos de las diferentes variables. 
  // Para habilitar esta opción se hará uso del método installHistoricalDataNode
  // installHistoricalDataNode: 
  addressSpace.installHistoricalDataNode(Horno_Temp);
  addressSpace.installHistoricalDataNode(Horno_KC);




  //////////////////////////////////////////////////////////////////

  // MÉTODOS

  //////////////////////////////////////////////////////////////////

  // OPC-UA permite servir métodos a los clientes. Estos son un nodo más del namespace que actuan como funciones del servidor que ejecutan acciones específicas: consulta de datos, cálculos, configuraciones, etc.
  // Tienen parámetros de entrada y devuelven un valor de salida. Son útiles para automatizar operaciones en el servidor, evitando las operaciones manuales con variables e impidiendo el acceso a variables sensibles. 
  // En nuestro caso serán útiles para servir las fases de equipamiento en el servidor OPC-UA

  // A la hora de crear un método utilizaremos el método addMethod del namespace para crear el nódo método. Este nodo se tiene que asociar a un objeto ya existente en el namespace.
  // Una vez creado el nodo método, éste se asociará a una función javascript con el método bindMethod. Esta función ejecutará las acciones específicas del método. 
  // 
  //        Documentación addMethod: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.namespace.html#addmethod
  //        Documentación bindMethod: https://node-opcua.github.io/api_doc/2.32.0/classes/node_opcua.uamethod.html#bindmethod
  //                                  https://node-opcua.github.io/api_doc/2.32.0/modules/node_opcua.html#methodfunctor

  // Creación de un método asociado a un objeto del namespace. En este caso al objeto device (PasarelaModbusOPCUA). El método tiene los mismos atributos que un nodo, pero, a mayores, es necesario indicar los parámetros de entrada y los valores de salida.
  const method = namespace.addMethod(device, {

    browseName: "Bark",
    nodeId: "ns=1;s=bark",
    componentOf: device,
    inputArguments: [
      {
        name: "nbBarks",
        description: { text: "specifies the number of time I should bark" },
        dataType: opcua.DataType.UInt32
      }, {
        name: "volume",
        description: { text: "specifies the sound volume [0 = quiet ,100 = loud]" },
        dataType: opcua.DataType.UInt32
      }
    ],

    outputArguments: [{
      name: "Barks",
      description: { text: "the generated barks" },
      dataType: opcua.DataType.String,
      valueRank: 1
    }]
  });

  // Permisos del método
  method.outputArguments.userAccessLevel = opcua.makeAccessLevelFlag("CurrentRead");
  method.inputArguments.userAccessLevel = opcua.makeAccessLevelFlag("CurrentRead");

  // Callback del método. Para añadir la función a ejecutar necesitamos asociar una callback al nodo del método

  // Modelo callback: https://node-opcua.github.io/api_doc/2.32.0/modules/node_opcua.html#methodfunctorcallback
  // Modelo parámetro de salida: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.callmethodresultoptions.html 
  method.bindMethod((inputArguments, context, callback) => {

    // Se lee los argumentos de entrada
    const nbBarks = inputArguments[0].value;
    const volume = inputArguments[1].value;


    // Operaciones a realizar por el método
    console.log("Hello World ! I will bark ", nbBarks, " times");
    console.log("the requested volume is ", volume, "");
    const sound_volume = Array(volume).join("!");


    if (nbBarks < 100) {
      const barks = [];
      for (let i = 0; i < nbBarks; i++) {
        barks.push("Whaff" + sound_volume);
      }



      // Se devuelve el valor de salida
      const callMethodResult = {
        statusCode: opcua.StatusCodes.Good,
        outputArguments: [{
          dataType: opcua.DataType.String,
          arrayType: opcua.VariantArrayType.Array,
          value: barks
        }]
      };
      callback(null, callMethodResult);
    }
    else {
      const callMethodResult = {
        statusCode: opcua.StatusCodes.Bad,
        outputArguments: [{
          dataType: opcua.DataType.String,
          arrayType: opcua.VariantArrayType.Array,
          value: ""
        }]
      };
      callback(null, callMethodResult);
    }




  });


  let nonExclusiveLimitAlarmType = addressSpace.findEventType('NonExclusiveLimitAlarmType')

  let alarmaTempHorno = namespace.instantiateNonExclusiveLimitAlarm(nonExclusiveLimitAlarmType, {
    componentOf: ME_HORNO,
    conditionSource: Horno_Temp,
    browseName: 'Fallo al calentar el horno',
    message: 'ATENCIÓN DEMASIADA TEMPERATURA EN EL HORNO',
    displayName: [
      new LocalizedText({ text: 'PELIGRO TEMPERATURA HORNO', locale: 'es-ES' }),
      new LocalizedText({ text: 'DANGER TEMPERATURE FURNANCE', locale: 'en-US' })
    ],
    description: 'Blah, blah, blah...',
    optionals: [
      'ConfirmedState', 'Confirm'
    ],
    inputNode: Horno_Temp,
    highLimit: 100,
    highHighLimit: 130,
    lowLimit: 0
  })

  eventObjects.Horno_Temp = Horno_Temp
  eventObjects.alarmaTempHorno = alarmaTempHorno



  //////////////////////////////////////////////////////////////////

  // CREACIÓN DE VISTAS

  //////////////////////////////////////////////////////////////////


  // Gracias al sistema de referencias, OPC-UA permite crear vistas donde poder organizar la información (los nodos) de acuerdo a diferentes criterios de organización: alarmas, magnitudes físicas, pantallas de operador, etc.


  // VISTA DE LAS TEMPERATURAS (PODEMOS PONER AQUÍ TODAS LAS TEMPS DEL PROYECTO)
  // Para crear una vista tenemos que crear un nuevo nodo en la carpeta views del namespace. Para ellos se emplea el método addView del namespace.
  //      Documentación: https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.namespace.html#addview 
  //                      https://node-opcua.github.io/api_doc/2.32.0/interfaces/node_opcua.addviewoptions.html 

  const viewEx = namespace.addView({
    "organizedBy": addressSpace.rootFolder.views,
    "browseName": "Temperaturas"
  });


  // Una vez creada el nodo vista a este se le añaden las referencias que queramos con el método addReference
  //       Documentación: https://node-opcua.github.io/api_doc/2.32.0/classes/node_opcua.uaview.html#addreference
  viewEx.addReference({
    "referenceType": "Organizes",
    "nodeId": Horno_Temp.nodeId
  });

  viewEx.addReference({
    "referenceType": "Organizes",
    "nodeId": Horno_MOD_SP_TEnf.nodeId
  });

  // Añadimos una vista con las alarmas
  const viewAl = namespace.addView({
    "organizedBy": addressSpace.rootFolder.views,
    "browseName": "Alarmas"
  });

  viewAl.addReference({
    "referenceType": "Organizes",
    "nodeId": alarmaTempHorno.nodeId
  });


  done();
}
